def amicable_numbers_sum(limit):
    def get_divisors_sum(n):
        divisors_sum = 0
        for i in range(1, n):
            if n % i == 0:
                divisors_sum += i
        return divisors_sum

    amicable_sum = 0
    for num in range(1, limit):
        div_sum = get_divisors_sum(num)
        if div_sum != num and get_divisors_sum(div_sum) == num:
            amicable_sum += num

    return amicable_sum

