def get_median(list1, list2, n):
    """
    Find median of two sorted arrays of same size
    """
    # If length of array is one
    if n == 1:
        return (list1[0] + list2[0]) / 2

    # If length of array is two
    if n == 2:
        return (max(list1[0], list2[0]) + min(list1[1], list2[1])) / 2

    # If length of array is odd
    if n % 2 == 1:
        # Find the middle element
        mid = n // 2
        # If middle element of list1 is smaller than middle element of list2
        if list1[mid] <= list2[mid]:
            # If middle element of list1 is greater than or equal to previous element of list1
            if list1[mid - 1] >= list2[mid - 1]:
                return list1[mid]
            else:
                return list2[mid - 1]
        else:
            # If middle element of list2 is greater than or equal to previous element of list2
            if list2[mid - 1] >= list1[mid - 1]:
                return list2[mid]
            else:
                return list1[mid - 1]

    # If length of array is even
    else:
        # Find the middle elements
        mid = n // 2
        # If middle element of list1 is smaller than middle element of list2
        if list1[mid] <= list2[mid]:
            # If middle element of list1 is greater than or equal to previous element of list1
            if list1[mid - 1] >= list2[mid - 1]:
                return (list1[mid] + list1[mid - 1]) / 2
            else:
                return (list1[mid] + list2[mid - 1]) / 2
        else:
            # If middle element of list2 is greater than or equal to previous element of list2
            if list2[mid - 1] >= list1[mid - 1]:
                return (list2[mid] + list2[mid - 1]) / 2
            else:
                return (list2[mid] + list1[mid - 1]) / 2

if __name__ == "__main__":
    assert get_median([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5) == 16.0
    print("All tests passed successfully")

