# Using Sieve of Eratosthenes with a more explicit approach
def count_primes_sieve(n):
    if n < 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False

    return sum(sieve)

print(count_primes_sieve(5)) # Output: 2
print(count_primes_sieve(10)) # Output: 4
print(count_primes_sieve(0)) # Output: 0
print(count_primes_sieve(1)) # Output: 0

