def find_amicable_pairs(limit):
    def get_divisors_sum(n):
        divisors_sum = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i and n // i != n:
                    divisors_sum += n // i
        return divisors_sum

    amicable_pairs = []
    for num in range(2, limit):
        div_sum = get_divisors_sum(num)
        if div_sum != num and get_divisors_sum(div_sum) == num:
            pair = (num, div_sum)
            if pair not in amicable_pairs and (div_sum, num) not in amicable_pairs:
                amicable_pairs.append(pair)

    return amicable_pairs

