def get_median(list1, list2, n):
    """
    Find median of two sorted arrays of same size
    """
    # merge both arrays into one array
    merged = []
    i = j = 0
    while i < n and j < n:
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1

    # add remaining elements
    while i < n:
        merged.append(list1[i])
        i += 1

    while j < n:
        merged.append(list2[j])
        j += 1

    # find median
    if len(merged) % 2 == 0:
        return (merged[len(merged)//2 - 1] + merged[len(merged)//2]) / 2
    else:
        return merged[len(merged)//2]

