def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    # Define vowels and their corresponding shifted versions
    vowel_shift = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.lower() if char.isupper() else char.upper()

            # Replace vowels with shifted version
            if swapped_char in vowel_shift:
                encoded_char = vowel_shift[swapped_char]
            else:
                encoded_char = swapped_char

            result.append(encoded_char)
        else:
            result.append(char)

    return ''.join(result)

# Test cases
