# Final concise solution
def replace_blank_final(string, char):
    """
    Replaces all blank spaces in a string with the given character.

    Args:
        string (str): The input string
        char (str): The character to replace spaces with

    Returns:
        str: The modified string with spaces replaced

    Examples:
        >>> replace_blank_final("hello people", '@')
        'hello@people'
        >>> replace_blank_final("a b c d", '-')
        'a-b-c-d'
    """
    return string.replace(' ', char)

