def tuple_intersection(tuple_list1, tuple_list2):
    # Convert each tuple in both lists to a set for easier comparison
    # and then convert back to tuples to maintain order consistency
    set1 = {tuple(sorted(t)) for t in tuple_list1}
    set2 = {tuple(sorted(t)) for t in tuple_list2}

    # Find intersection of sets
    intersection = set1 & set2

    # Convert back to original tuple format (maintaining original order)
    result = set()
    for t in intersection:
        # Find the original tuple from tuple_list1 or tuple_list2 that matches this sorted tuple
        for orig_t in tuple_list1:
            if tuple(sorted(orig_t)) == t:
                result.add(orig_t)
                break
        else:
            for orig_t in tuple_list2:
                if tuple(sorted(orig_t)) == t:
                    result.add(orig_t)
                    break

    return result

