from collections import defaultdict

def largest_subset(nums):
    # Create a graph where an edge from a to b means b % a == 0
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[j] % nums[i] == 0:
                graph[nums[i]].append(nums[j])
            elif nums[i] % nums[j] == 0:
                graph[nums[j]].append(nums[i])

    # Find the longest path in the DAG (topological sort approach)
    def dfs(node, memo):
        if node not in memo:
            memo[node] = 1 + max((dfs(neighbor, memo) for neighbor in graph[node]), default=0)
        return memo[node]

    memo = {}
    return max(dfs(num, memo) for num in set(nums))

