def max_aggregate(lst):
    # Create a dictionary to store the aggregate scores
    aggregate = {}

    # Iterate through the list of tuples
    for name, score in lst:
        if name in aggregate:
            aggregate[name] += score
        else:
            aggregate[name] = score

    # Find the name with the maximum aggregate
    max_name = max(aggregate, key=aggregate.get)

    # Return the name and its maximum aggregate
    return (max_name, aggregate[max_name])

