        return 3 + 0 + 2
    else:
        # Initialize the first three Perrin numbers
        p0, p1, p2 = 3, 0, 2
        total = p0 + p1 + p2

        # Calculate subsequent Perrin numbers and add to total
        for i in range(3, n):
            p_next = p0 + p1
            total += p_next
            # Shift the values for next iteration
            p0, p1, p2 = p1, p2, p_next

        return total

