def get_median(list1, list2, n):
    """
    Find median of two sorted arrays of same size
    """
    # If length of array is one
    if n == 1:
        return (list1[0] + list2[0]) / 2

    # If length of array is two
    if n == 2:
        return (max(list1[0], list2[0]) + min(list1[1], list2[1])) / 2

    # If length of array is odd
    if n % 2 == 1:
        # Find the middle element
        mid = n // 2
        # If middle element of first array is greater than middle element of second array
        if list1[mid] > list2[mid]:
            # If middle element of first array is greater than last element of second array
            if list1[mid] > list2[n - 1]:
                return list2[n - 1]
            # If middle element of first array is less than first element of second array
            elif list1[mid] < list2[0]:
                return list2[0]
            # If middle element of first array is between first and last element of second array
            else:
                return list1[mid]
        # If middle element of first array is less than middle element of second array
        else:
            # If middle element of first array is greater than last element of first array
            if list2[mid] > list1[n - 1]:
                return list1[n - 1]
            # If middle element of first array is less than first element of first array
            elif list2[mid] < list1[0]:
                return list1[0]
            # If middle element of first array is between first and last element of first array
            else:
                return list2[mid]

    # If length of array is even
    else:
        # Find the middle elements
        mid1 = n // 2
        mid2 = n // 2 - 1
        # If middle element of first array is greater than middle element of second array
        if list1[mid1] > list2[mid2]:
            # If middle element of first array is greater than last element of second array
            if list1[mid1] > list2[n - 1]:
                return list2[n - 1]
            # If middle element of first array is less than first element of second array
            elif list1[mid1] < list2[0]:
                return list2[0]
            # If middle element of first array is between first and last element of second array
            else:
                return list1[mid1]
        # If middle element of first array is less than middle element of second array
        else:
            # If middle element of first array is greater than last element of first array
            if list2[mid2] > list1[n - 1]:
                return list1[n - 1]
            # If middle element of first array is less than first element of first array
            elif list2[mid2] < list1[0]:
                return list1[0]
            # If middle element of first array is between first and last element of first array
            else:
                return list2[mid2]

