def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        divisors = []
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divisors.append(i)
                if i != num // i and num // i != num:
                    divisors.append(num // i)
        return sum(divisors)

    amicable_sum = 0

    for a in range(2, n):
        b = sum_of_divisors(a)
        if a != b and sum_of_divisors(b) == a:
            amicable_sum += a

    return amicable_sum

