    Find the median of two sorted arrays of equal length.

    Args:
        list1 (list): First sorted array.
        list2 (list): Second sorted array.
        n (int): Length of both arrays.

    Returns:
        float: The median of the combined arrays.

    Example:
        >>> get_median([1, 12, 15, 26, 38], [2, 13, 17, 30, 45], 5)
        16.0
    """
    # If we reach at the end of either array,
    # return the minimum of remaining elements
    if n == 0:
        return -1
    if n == 1:
        return (list1[0] + list2[0]) / 2
    if n == 2:
        return (max(list1[0], list2[0]) + min(list1[1], list2[1])) / 2

    # Find medians of both arrays
    m1 = median(list1, n)
    m2 = median(list2, n)

    # If medians are equal, return either one
    if m1 == m2:
        return m1

    # If m1 < m2, then median must exist in list1[m1...]
    # and list2[...m2]
    if m1 < m2:
        if n % 2 == 0:
            return get_median(list1[n // 2 - 1:], list2[:n // 2 + 1], n - n // 2 + 1)
        else:
            return get_median(list1[n // 2:], list2[:n // 2 + 1], n - n // 2)
    else:
        # If m1 > m2, then median must exist in list1[...m1]
        # and list2[m2...]
        if n % 2 == 0:
            return get_median(list1[:n // 2 + 1], list2[n // 2 - 1:], n - n // 2 + 1)
        else:
            return get_median(list1[:n // 2 + 1], list2[n // 2:], n - n // 2)


def median(arr, n):
    """
    Helper function to calculate median of an array.

    Args:
        arr (list): Input array.
        n (int): Length of the array.

    Returns:
        float: Median value of the array.
    """
    if n % 2 == 0:
        return (arr[n // 2] + arr[n // 2 - 1]) / 2
    else:
        return arr[n // 2]


