def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth = max(depth, len(current))
            for v in current.values():
                stack.append(v)

    return depth

