def bell_Number(n):
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        bell = [0] * (n + 1)
        bell[0] = 1
        for i in range(1, n + 1):
            bell[i] = 0
            for j in range(i):
                bell[i] += bell[j] * comb(i - 1, j)
        return bell[n]

def comb(n, k):
    if k > n or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    return fact(n) // (fact(k) * fact(n - k))

def fact(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

