def count_Primes_nums(n):
    if n < 2:
        return 0

    prime = [1] * n
    prime[0] = prime[1] = 0

    for i in range(2, int(n ** 0.5) + 1):
        if prime[i]:
            for j in range(i * i, n, i):
                prime[j] = 0

    return sum(prime)

