def get_total_number_of_sequences_v2(m, n):
    # Memoization dictionary
    memo = {}

    def helper(max_val, remaining_length):
        # Base cases
        if remaining_length == 0:
            return 1
        if max_val < 1 or remaining_length < 0:
            return 0

        # Check memo
        if (max_val, remaining_length) in memo:
            return memo[(max_val, remaining_length)]

        count = 0
        # Try all possible values for current position
        for val in range(1, max_val + 1):
            # The next value must be at least twice the current value
            if val * 2 <= max_val:
                count += helper(val, remaining_length - 1)

        memo[(max_val, remaining_length)] = count
        return count

    return helper(m, n)

