    for i in range(1, m + 1):
        dp[i][1] = 1

    # Fill the dp table
    for length in range(2, n + 1):
        for max_val in range(1, m + 1):
            # For each possible last value, sum up valid previous sequences
            for prev_val in range(1, max_val + 1):
                if prev_val * 2 <= max_val:
                    dp[max_val][length] += dp[prev_val][length - 1]

    # Sum all sequences of length n
    result = 0
    for i in range(1, m + 1):
        result += dp[i][n]

    return result

