def dict_depth_deque(d):
    if not isinstance(d, dict) or not d:
        return 0

    queue = deque([(d, 1)])
    max_depth = 0

    while queue:
        current, depth = queue.popleft()
        max_depth = max(max_depth, depth)

        if isinstance(current, dict):
            for v in current.values():
                queue.append((v, depth + 1))

    return max_depth

