# Alternative implementation using manual calculation of combinations
def sum_Of_product_v2(n):
    def combination(n, r):
        if r > n or r < 0:
            return 0
        if r == 0 or r == n:
            return 1
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

    total = 0
    for i in range(n):
        total += combination(n, i) * combination(n, i + 1)
    return total

print(sum_Of_product_v2(3)) # Expected output: 15

# Another approach using the identity: sum of C(n,i)*C(n,i+1) = C(2n,n+1)
def sum_Of_product_v3(n):
    return math.comb(2 * n, n + 1)

print(sum_Of_product_v3(3)) # Expected output: 15

