def amicable_numbers_sum(n):
    def get_divisors_sum(num):
        divisors = [i for i in range(1, num) if num % i == 0]
        return sum(divisors)

    amicable_sum = 0

    for i in range(1, n):
        div_sum_i = get_divisors_sum(i)
        if div_sum_i != i and div_sum_i < n:
            div_sum_j = get_divisors_sum(div_sum_i)
            if div_sum_j == i:
                amicable_sum += i

    return amicable_sum

