    if len(l2) > len(l1):
        return False
    for i in range(len(l1)):
        if l1[i] == l2[0]:
            k = 0
            for j in range(i,len(l1)):
                if l1[j] == l2[k]:
                    k += 1
                    if k == len(l2):
                        return True
                else:
                    break
    return False

