def unique_sublists(input_list):
    # Convert each sublist to a tuple
    tuple_list = [tuple(sublist) for sublist in input_list]

    # Count occurrences of each tuple
    count_dict = {}
    for tpl in tuple_list:
        if tpl in count_dict:
            count_dict[tpl] += 1
        else:
            count_dict[tpl] = 1

    return count_dict

