def get_total_number_of_sequences(m, n):
    # Create a 2D array to store the results of subproblems
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: if n is 0, there's one sequence (empty sequence)
    for i in range(1, m + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # For each position, we can choose any number from 1 to i
            # But it must be at least twice the previous element
            for k in range(1, i + 1):
                if k * 2 <= i:
                    dp[i][j] += dp[k][j - 1]

    return dp[m][n]

# Test the function
print(get_total_number_of_sequences(10, 4))  # Expected output: 4

# Let's also verify with a simpler example
def get_total_number_of_sequences_v2(m, n):
    # Memoization dictionary
    memo = {}

    def helper(prev, remaining):
        # Base case: no more elements needed
        if remaining == 0:
            return 1

        # If previous value is too large, no valid sequences
        if prev > m:
            return 0

        # Check memoization
        if (prev, remaining) in memo:
            return memo[(prev, remaining)]

        count = 0
        # Try all possible next values
        for next_val in range(prev, m + 1):
            if next_val >= 2 * prev:
                count += helper(next_val, remaining - 1)

        memo[(prev, remaining)] = count
        return count

    # Start with all possible first values
    total = 0
    for first in range(1, m + 1):
        total += helper(first, n - 1)

    return total

