import math


def sum_Of_product(n):
    total = 0
    for i in range(n):
        total += math.comb(n, i) * math.comb(n, i + 1)
    return total


print(sum_Of_product(3))  # Expected output: 15

# Alternative implementation using manual calculation of combinations
def sum_of_product_alternative(n):
    def combination(n, r):
        if r > n or r < 0:
            return 0
        if r == 0 or r == n:
            return 1
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))

    total = 0
    for i in range(n):
        total += combination(n, i) * combination(n, i + 1)
    return total


print(sum_of_product_alternative(3))  # Expected output: 15

# Another approach using the identity that sum of C(n,i)*C(n,i+1) for i=0 to n-1 equals C(2n,n-1)
def sum_of_product_identity(n):
    if n <= 0:
        return 0
    return math.comb(2 * n, n - 1)


print(sum_of_product_identity(3))  # Expected output: 15

# Test cases
