import heapq

def large_product(list1, list2, n):
    # Generate all possible products
    products = []
    for num1 in list1:
        for num2 in list2:
            products.append(num1 * num2)

    # Use heapq.nlargest to get the n largest products
    return heapq.nlargest(n, products)

