def even_Power_Sum_v3(n):
    # Sum of first n even numbers raised to the fifth power
    # = 2^5 * (1^5 + 2^5 + ... + n^5)
    # = 32 * (n(n+1)/2)^2 * (2n^2 + 2n - 1)/3
    # = 32 * (n^2(n+1)^2/4) * (2n^2 + 2n - 1)/3
    # = 8 * n^2(n+1)^2(2n^2 + 2n - 1)/3
    return 8 * n**2 * (n+1)**2 * (2*n**2 + 2*n - 1) // 3

