from collections import defaultdict

def dict_depth_defaultdict(d):
    if not isinstance(d, dict) or not d:
        return 0

    def get_max_depth(obj, current_depth=1):
        if not isinstance(obj, dict):
            return current_depth

        max_depth = current_depth
        for value in obj.values():
            max_depth = max(max_depth, get_max_depth(value, current_depth + 1))

        return max_depth

    return get_max_depth(d)

