# Alternative solution using a class-based approach
class DictDepth:
    def __init__(self):
        self.max_depth = 0

    def calculate(self, d, current_depth=1):
        if not isinstance(d, dict) or not d:
            return current_depth

        self.max_depth = max(self.max_depth, current_depth)
        for value in d.values():
            self.calculate(value, current_depth + 1)

        return self.max_depth

def dict_depth_class(d):
