def get_pairs_count(arr, sum):
    # Create a dictionary to store frequency of each element
    freq = {}
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    count = 0
    # Iterate through each element in the array
    for num in arr:
        complement = sum - num
        # If complement exists in the frequency map
        if complement in freq:
            # If complement is same as current number, we need to subtract 1
            # because we don't want to count the same element twice
            if complement == num:
                count += freq[complement] - 1
            else:
                count += freq[complement]

    # Since we are counting pairs (i,j) and (j,i) separately, we divide by 2
    return count // 2

