# Alternative solution using stack
def dict_depth_stack(d):
    if not isinstance(d, dict) or not d:
        return 0

    stack = [d]
    depth = 0

    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            depth += 1
            stack.extend(current.values())

    return depth

print(dict_depth_stack({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using recursion with helper function
def dict_depth_helper(d):
    def helper(obj, level):
        if not isinstance(obj, dict) or not obj:
            return level
        return max(helper(v, level + 1) for v in obj.values())

    return helper(d, 0)

print(dict_depth_helper({'a':1, 'b': {'c': {'d': {}}}})) # 4

# Alternative solution using iteration
def dict_depth_iterative(d):
    if not isinstance(d, dict) or not d:
        return 0

    max_depth = 1
    queue = [(d, 1)]

    while queue:
        current_dict, current_depth = queue.pop(0)
        if isinstance(current_dict, dict):
            max_depth = max(max_depth, current_depth)
            for value in current_dict.values():
                if isinstance(value, dict):
                    queue.append((value, current_depth + 1))

    return max_depth

print(dict_depth_iterative({'a':1, 'b': {'c': {'d': {}}}})) # 4

