    # Initialize pointers for both arrays
    i = 0
    j = 0

    # Counter to track the current position in merged array
    count = 0

    # Traverse both arrays until one is exhausted
    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            count += 1
            if count == k:
                return arr1[i]
            i += 1
        else:
            count += 1
            if count == k:
                return arr2[j]
            j += 1

    # If elements in arr1 are left
    while i < len(arr1):
        count += 1
        if count == k:
            return arr1[i]
        i += 1

    # If elements in arr2 are left
    while j < len(arr2):
        count += 1
        if count == k:
            return arr2[j]
        j += 1

