from collections import defaultdict

def largest_subset(nums):
    # Create a graph where an edge from a to b means b is divisible by a
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[j] % nums[i] == 0:
                graph[nums[i]].append(nums[j])
            elif nums[i] % nums[j] == 0:
                graph[nums[j]].append(nums[i])

    # Find the longest path in the DAG
    memo = {}

    def dfs(node):
        if node in memo:
            return memo[node]

        max_length = 1
        for neighbor in graph[node]:
            max_length = max(max_length, 1 + dfs(neighbor))

        memo[node] = max_length
        return max_length

    # Try starting from each node
    result = 0
    for num in nums:
        result = max(result, dfs(num))

    return result

