def two_unique_nums(nums):
    # Count occurrences of each number
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    # Filter numbers that appear exactly once
    result = [num for num, cnt in count.items() if cnt == 1]

    return result

