from collections import defaultdict

def largest_subset(nums):
    # Create a graph where an edge from a to b means b % a == 0
    # and a < b
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[j] % nums[i] == 0:
                graph[nums[i]].append(nums[j])

    # Find the longest path in the DAG
    memo = {}
    def dfs(node):
        if node not in memo:
            memo[node] = 1 + max((dfs(nei) for nei in graph[node]), default=0)
        return memo[node]

    return max(dfs(num) for num in nums)

# Test
print(largest_subset([1, 3, 6, 13, 17, 18]))  # Expected: 4

# Explanation:
# The largest divisible subset is [1, 3, 6, 18] or [1, 3, 6, 18], etc.
# The path in the graph would be 1 -> 3 -> 6 -> 18 (or similar)
# This gives us a subset of size 4.

