def sum_of_digits_final(lst):
    """
    Compute the sum of digits of each number in the list.

    Args:
        lst: List of integers

    Returns:
        int: Sum of all digits

    Example:
        >>> sum_of_digits_final([10,2,56])
        14
    """
    total = 0
    for num in lst:
        while num > 0:
            total += num % 10
            num //= 10
    return total

