def tuple_to_dict(input_tuple):
    # Check if the tuple has an even number of elements
    if len(input_tuple) % 2 != 0:
        raise ValueError("Tuple must have an even number of elements")

    # Create a dictionary by pairing adjacent elements
    result_dict = {}
    for i in range(0, len(input_tuple), 2):
        key = input_tuple[i]
        value = input_tuple[i + 1]
        result_dict[key] = value

    return result_dict

# Test the function
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}

